import {loadCatalog} from './data.js';
import {enhanceFilters} from './filter-menu.js';
const app=document.querySelector('#outcomes-app');
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,catalog,models,year=1,week='',query='';
const normal=s=>s.toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const terms=()=>normal(query).split(' ').filter(Boolean);
function matches(s,o){const text=normal([s.week,s.title,s.system,o.text,...o.structureIds.map(id=>catalog.byId.get(id)?.name||'')].join(' '));return terms().every(t=>text.includes(t));}
function sessions(){return data.sessions.filter(s=>s.year===year&&s.outcomes.some(o=>matches(s,o)));}
function url(){const u=new URL(location.href);u.search='';u.searchParams.set('year',year);if(week)u.searchParams.set('week',week);if(query)u.searchParams.set('q',query);history.replaceState(null,'',u);}
function controls(){app.innerHTML=`<section class="outcomes-heading"><div class="eyebrow">Human structure</div><h1>Learning outcomes</h1><p>Browse your teaching weeks and explore related anatomy.</p></section><section class="outcomes-controls"><div class="segments outcome-years" aria-label="Teaching year">${[1,2].map(y=>`<button data-year="${y}" aria-pressed="${year===y}">Year ${y}</button>`).join('')}</div><label class="outcome-search">Search outcomes<input type="search" id="outcome-search" placeholder="A structure, topic or week number" value="${escape(query)}"></label><div id="week-controls"></div></section><p id="outcome-count" role="status"></p><div id="outcome-content"></div>`;results();}
function modelLinks(ids){return ids.map(id=>`<a class="outcome-link model-outcome-link" href="./?model=${encodeURIComponent(id)}">${escape(models.find(m=>m.id===id)?.name||id)} <span aria-hidden="true">↗</span></a>`).join('');}
function results(){const all=sessions();if(!all.some(s=>s.week===week))week=all[0]?.week||'';const index=all.findIndex(s=>s.week===week),s=all[index];
 const nav=app.querySelector('#week-controls');nav.innerHTML=`<div class="week-navigation"><button class="secondary" data-step="-1" ${index<=0?'disabled':''} aria-label="Previous teaching week">←</button><label>Teaching week<select data-filter="week" id="outcome-week">${all.map(w=>`<option value="${w.week}" ${w.week===week?'selected':''}>Week ${w.week} · ${escape(w.title)}</option>`).join('')||'<option>No matching weeks</option>'}</select></label><button class="secondary" data-step="1" ${index<0||index===all.length-1?'disabled':''} aria-label="Next teaching week">→</button></div>`;enhanceFilters(nav);
 const total=all.reduce((n,s)=>n+s.outcomes.filter(o=>matches(s,o)).length,0);app.querySelector('#outcome-count').textContent=`${total} ${query?'matching ':''}outcomes · ${all.length} teaching weeks in Year ${year}`;
 const host=app.querySelector('#outcome-content');if(!s){host.innerHTML='<div class="outcome-empty"><h2>No matching outcomes</h2><p>Try another search or switch year.</p></div>';url();return;}
 host.innerHTML=`<section class="outcome-session"><div class="outcome-session-heading"><div><div class="eyebrow">Year ${year} · Week ${s.week}</div><h2>${escape(s.title)}</h2><p class="outcome-system">${escape(s.system)} · ${index+1} of ${all.length} weeks</p></div><a class="icon-link" href="./documents/year-${year}-learning-outcomes.pdf#page=${s.pages[0]}" target="_blank" rel="noopener">Source PDF ↗</a></div>${s.summary?`<div class="session-outcome"><strong>Session learning outcome</strong><p>${escape(s.summary)}</p></div>`:''}<ol class="outcomes-list">${s.outcomes.map((o,i)=>({o,i})).filter(({o})=>matches(s,o)).map(({o,i})=>`<li value="${i+1}" id="${o.id}"><p>${escape(o.text)}</p>${o.structureIds.length?`<div class="outcome-links" aria-label="Related library structures">${o.structureIds.map(id=>`<a class="outcome-link" href="./library.html?structure=${encodeURIComponent(id)}">${escape(catalog.byId.get(id).name)} <span aria-hidden="true">↗</span></a>`).join('')}</div>`:o.relatedModelIds.length?`<details class="outcome-models"><summary>Explore related models</summary><div class="outcome-links">${modelLinks(o.relatedModelIds)}</div><small>Related anatomy; these models may cover only part of this outcome.</small></details>`:'<small class="outcome-gap">No matching anatomy in the current library yet.</small>'}</li>`).join('')}</ol><details class="outcome-provenance"><summary>About these outcomes and links</summary><p>Outcome wording, week codes and system labels come from your supplied Year ${year} PDF. Library links are suggested from named structures within the session’s related models. They are revision aids, not confirmation that a learning outcome is fully covered. Broad topics without a matching structure link to related models where available.</p></details></section>`;url();}
app.addEventListener('click',event=>{const y=event.target.closest('[data-year]');if(y){year=Number(y.dataset.year);week='';controls();return;}const b=event.target.closest('[data-step]');if(b&&!b.disabled){const all=sessions();week=all[all.findIndex(s=>s.week===week)+Number(b.dataset.step)].week;results();}});
app.addEventListener('input',event=>{if(event.target.id==='outcome-search'){query=event.target.value;week='';results();}});
app.addEventListener('change',event=>{if(event.target.id==='outcome-week'){week=event.target.value;results();}});
try{const responses=await Promise.all([fetch('./data/learning-outcomes.json'),fetch('./data/models.json'),loadCatalog()]);if(!responses[0].ok||!responses[1].ok)throw Error('Data unavailable');data=await responses[0].json();models=await responses[1].json();catalog=responses[2];const params=new URLSearchParams(location.search);year=params.get('year')==='2'?2:1;week=params.get('week')||'';query=params.get('q')||'';controls();}catch(error){app.innerHTML='<section class="outcome-empty"><h1>Learning outcomes could not load</h1><p>Reload the page to try again.</p><button class="secondary" onclick="location.reload()">Reload</button></section>';}
